/*
 * A LEARNER READS HER CONVERSATION WITH THE COACH (DBU-07): only her own, whatever is sent.
 * With stepId, only the messages about that homework (one of her shared homework steps).
 * Reading marks the coach's messages that are shown as read, and rings her bell once if it
 * marked any, so the unread count in the tabs clears (the bell re-reads, and then marks nothing).
 * A homework tag names the homework only while she can see it (shared).
 */
(async () => {
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const R = Noodl.Records;
    const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
    const stepId = String(Inputs.stepId || '');
    const steps = (await q('Step', { learner: { equalTo: me } })).filter((s) => s.shared === true && s.kind === 'homework');
    if (stepId && !steps.some((s) => s.objectId === stepId)) { Outputs.refused(); return; }

    let rows = await q('Message', { learner: { equalTo: me } });
    if (stepId) rows = rows.filter((m) => m.step === stepId);
    rows.sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));

    const others = [...new Set(rows.map((m) => m.author).filter((a) => a !== me))];
    const people = others.length ? await q('_User', { objectId: { containedIn: others } }) : [];
    const users = await q('_User', { objectId: { equalTo: me } });
    const user = users[0] || {};
    const nameOf = (id) => { const u = people.find((p) => p.objectId === id); return String((u && u.name) || 'Coach').split(' ')[0]; };
    const titleOf = (id) => { const s = steps.find((x) => x.objectId === id); return s ? String(s.title || '') : ''; };

    const now = new Date().toISOString();
    const unread = rows.filter((m) => m.author !== me && !m.readAt);
    Outputs.messages = rows.map((m) => ({
      id: m.objectId,
      mine: m.author === me,
      who: m.author === me ? '' : nameOf(m.author),
      body: String(m.body || ''),
      at: m.createdAt,
      stepId: m.step || '',
      stepTitle: m.step ? titleOf(m.step) : '',
      attachments: (Array.isArray(m.attachments) ? m.attachments : []).map((a) => ({ file: a.file, fileName: a.name })),
      isNew: m.author !== me && !m.readAt
    }));
    Outputs.me = { name: user.name || '', timezone: user.timezone || '' };
    Outputs.emailOn = !user.emailOptOutAt;
    for (const m of unread) await R.save(m.objectId, { readAt: now }, { className: 'Message' });
    if (unread.length) {
      await R.create('Doorbell', { learner: me, topic: 'message' }, { acl: { [me]: { read: true }, 'role:staff': { read: true } } });
    }
    Outputs.done();
  } catch (e) {
    console.error('[dbu:myMessages]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
